-- 7cc8f32d | ما هو الحديث الحسن؟
UPDATE qa_questions SET
  answer = 'الحديثُ الحسن عند ابن الصلاح في مقدمته — وهو محرِّرُ الفنّ الذي دارت عليه شروحُ من بعده — **قسمان** لا حدٌّ واحد، بعد أن ردّ ما سبقه من التعريفات بقوله: «كُلُّ هَذَا مُسْتَبْهَمٌ لَا يَشْفِي الْغَلِيلَ، وَلَيْسَ فِيمَا ذَكَرَهُ التِّرْمِذِيُّ وَالْخَطَّابِيُّ مَا يَفْصِلُ الْحَسَنَ مِنَ الصَّحِيحِ». قال: «أَنَّ الْحَدِيثَ الْحَسَنَ قِسْمَانِ»: (١) «الْحَدِيثُ الَّذِي لَا يَخْلُو رِجَالُ إِسْنَادِهِ مِنْ مَسْتُورٍ لَمْ تَتَحَقَّقْ أَهْلِيَّتُهُ»، «غَيْرَ أَنَّهُ لَيْسَ مُغَفَّلًا كَثِيرَ الْخَطَأِ فِيمَا يَرْوِيهِ، وَلَا هُوَ مُتَّهَمٌ بِالْكَذِبِ فِي الْحَدِيثِ»، ويكون متنُه «قَدْ عُرِفَ بِأَنْ رُوِيَ مِثْلُهُ أَوْ نَحْوُهُ مِنْ وَجْهٍ آخَرَ أَوْ أَكْثَرَ حَتَّى اعْتَضَدَ» بمتابعٍ أو شاهد، وعلى هذا القسم يتنزّل كلامُ الترمذي. (٢) «أَنْ يَكُونَ رَاوِيهِ مِنَ الْمَشْهُورِينَ بِالصِّدْقِ وَالْأَمَانَةِ، غَيْرَ أَنَّهُ لَمْ يَبْلُغْ دَرَجَةَ رِجَالِ الصَّحِيحِ، لِكَوْنِهِ يَقْصُرُ عَنْهُمْ فِي الْحِفْظِ وَالْإِتْقَانِ»، وعليه يتنزّل كلامُ الخطابي: «الْحَسَنُ مَا عُرِفَ مُخْرَجُهُ وَاشْتَهَرَ رِجَالُهُ»، «وَعَلَيْهِ مَدَارُ أَكْثَرِ الْحَدِيثِ، وَهُوَ الَّذِي يَقْبَلُهُ أَكْثَرُ الْعُلَمَاءِ، وَيَسْتَعْمِلُهُ عَامَّةُ الْفُقَهَاءِ»؛ قال ابنُ الصلاح: «وَكَأَنَّ التِّرْمِذِيَّ ذَكَرَ أَحَدَ نَوْعَيِ الْحَسَنِ، وَذَكَرَ الْخَطَّابِيُّ النَّوْعَ الْآخَرَ». ويُشترط في القسمين معًا: «وَيُعْتَبَرُ فِي كُلِّ هَذَا - مَعَ سَلَامَةِ الْحَدِيثِ مِنْ أَنْ يَكُونَ شَاذًّا وَمُنْكَرًا - سَلَامَتُهُ مِنْ أَنْ يَكُونَ مُعَلَّلًا». وأمّا رتبتُه فدون الصحيح لا مساويةٌ له: «الْحَسَنُ يَتَقَاصَرُ عَنِ الصَّحِيحِ»؛ فالصحيحُ من شرطه أن تثبت عدالةُ جميع رواته وضبطُهم وإتقانُهم، وذلك غيرُ مشترطٍ في الحسن. ومن أطلق على الحسن اسمَ الصحيح فإنما هو توسّعٌ في العبارة: «مَنْ سَمَّى الْحَسَنَ صَحِيحًا لَا يُنْكِرُ أَنَّهُ دُونَ الصَّحِيحِ الْمُقَدَّمِ الْمُبَيَّنِ أَوَّلًا، فَهَذَا إِذًا اخْتِلَافٌ فِي الْعِبَارَةِ دُونَ الْمَعْنَى».',
  reference = 'مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)، ت نور الدين عتر (دار الفكر بسوريا، ١٤٠٦هـ): ص٢٩–٣٢ و٣٧ و٤٠ (النوع الثاني: معرفة الحسن من الحديث) | الكلمات المفتاحية: الحديث الحسن',
  evidence = 'مقدمة ابن الصلاح ص٣٠ تسوق تعريفَي الخطابي والترمذي للحسن: الخطابيّ: «الْحَسَنُ مَا عُرِفَ مُخْرَجُهُ وَاشْتَهَرَ رِجَالُهُ»، «وَعَلَيْهِ مَدَارُ أَكْثَرِ الْحَدِيثِ، وَهُوَ الَّذِي يَقْبَلُهُ أَكْثَرُ الْعُلَمَاءِ، وَيَسْتَعْمِلُهُ عَامَّةُ الْفُقَهَاءِ»؛ والترمذيّ يريد به «أَنْ لَا يَكُونَ فِي إِسْنَادِهِ مَنْ يُتَّهَمُ بِالْكَذِبِ، وَلَا يَكُونَ حَدِيثًا شَاذًّا، وَيُرْوَى مِنْ غَيْرِ وَجْهٍ نَحْوُ ذَلِكَ». ثم ردّهما ابنُ الصلاح بنصٍّ صريح: «كُلُّ هَذَا مُسْتَبْهَمٌ لَا يَشْفِي الْغَلِيلَ، وَلَيْسَ فِيمَا ذَكَرَهُ التِّرْمِذِيُّ وَالْخَطَّابِيُّ مَا يَفْصِلُ الْحَسَنَ مِنَ الصَّحِيحِ»، وحرّره ص٣١ بقسمين: «أَنَّ الْحَدِيثَ الْحَسَنَ قِسْمَانِ»: أحدُهما «الْحَدِيثُ الَّذِي لَا يَخْلُو رِجَالُ إِسْنَادِهِ مِنْ مَسْتُورٍ لَمْ تَتَحَقَّقْ أَهْلِيَّتُهُ» ويعتضد بمتابعٍ أو شاهد، والثاني «أَنْ يَكُونَ رَاوِيهِ مِنَ الْمَشْهُورِينَ بِالصِّدْقِ وَالْأَمَانَةِ، غَيْرَ أَنَّهُ لَمْ يَبْلُغْ دَرَجَةَ رِجَالِ الصَّحِيحِ، لِكَوْنِهِ يَقْصُرُ عَنْهُمْ فِي الْحِفْظِ وَالْإِتْقَانِ». ⚠️ وعيبُ الجواب السابق أنه ساق تعريفًا مفردًا ‹عدل خفيف الضبط› **بلا نسبةٍ ولا موضع**، وهو تحريرُ من جاء بعد ابن الصلاح، فطُوِيَ به قسمُ المستور الذي يُجبَر بالاعتضاد. 🚩 وإطلاقُ ‹يُحتَجّ به كالصحيح عند جمهور المحدثين› يخالف نصَّ ص٣٢: «الْحَسَنُ يَتَقَاصَرُ عَنِ الصَّحِيحِ»، ونصَّ ص٤٠: «مَنْ سَمَّى الْحَسَنَ صَحِيحًا لَا يُنْكِرُ أَنَّهُ دُونَ الصَّحِيحِ الْمُقَدَّمِ الْمُبَيَّنِ أَوَّلًا، فَهَذَا إِذًا اخْتِلَافٌ فِي الْعِبَارَةِ دُونَ الْمَعْنَى».',
  verification_status = 'verified'
WHERE id = '7cc8f32d-d5e3-4164-95e8-3cf7a236a533'
  AND reference = 'كتب مصطلح الحديث | الكلمات المفتاحية: الحديث الحسن'
  AND evidence = 'تعريف مشهور عند علماء مصطلح الحديث.'
  AND answer = 'ما اتصل سنده بنقل عدل خفيف الضبط عن مثله إلى منتهاه، من غير شذوذ ولا علة، وهو دون الصحيح في القوة لكنه يُحتَجّ به كالصحيح عند جمهور المحدثين.';

-- 406f6138 | ما الفرق بين الحديث المتواتر وحديث الآحاد؟
UPDATE qa_questions SET
  answer = 'الفرقُ بينهما في المقدار المُفيد للعلم: فالمتواتر — كما حدَّه ابن الصلاح في مقدمته — «عِبَارَةٌ عَنِ الْخَبَرِ الَّذِي يَنْقُلُهُ مَنْ يَحْصُلُ الْعِلْمُ بِصِدْقِهِ ضَرُورَةً»، أي يُفيد اليقين القطعيّ بلا نظرٍ ولا استدلال، ويُشترط فيه أن يستمرّ ذلك في كلّ طبقات السند لا في بعضها: «وَلَا بُدَّ فِي إِسْنَادِهِ مِنِ اسْتِمْرَارِ هَذَا الشَّرْطِ فِي رُوَاتِهِ مِنْ أَوَّلِهِ إِلَى مُنْتَهَاهُ»؛ وما لم يبلغ ذلك فهو الآحاد، وعليه مدارُ عامّة المرويّ. وثلاثةُ تنبيهاتٍ منصوصةٍ في الموضع تُقيّد هذا التقسيم: (١) أنّ المتواتر عند ابن الصلاح مُدرَجٌ في المشهور، ومصطلحُه مأخوذٌ عن غير أهل الحديث: «وَمِنَ الْمَشْهُورِ: الْمُتَوَاتِرُ الَّذِي يَذْكُرُهُ أَهْلُ الْفِقْهِ وَأُصُولِهِ، وَأَهْلُ الْحَدِيثِ لَا يَذْكُرُونَهُ بِاسْمِهِ الْخَاصِّ الْمُشْعِرِ بِمَعْنَاهُ الْخَاصِّ»، «وَلَعَلَّ ذَلِكَ لِكَوْنِهِ لَا تَشْمَلُهُ صِنَاعَتُهُمْ، وَلَا يَكَادُ يُوجَدُ فِي رِوَايَاتِهِمْ». (٢) أنّ أمثلته عزيزةٌ جدًّا في المرويّ: «وَمَنْ سُئِلَ عَنْ إِبْرَازِ مِثَالٍ لِذَلِكَ فِيمَا يُرْوَى مِنَ الْحَدِيثِ أَعْيَاهُ تَطَلُّبُهُ» — ولذلك كان الغالبُ على أحاديث الأحكام أن تكون من الآحاد. (٣) أنّ كثرةَ الطرق في بعض الطبقات لا تكفي؛ فحديثُ «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ» — على شهرته — «لَيْسَ مِنْ ذَلِكَ بِسَبِيلٍ، وَإِنْ نَقَلَهُ عَدَدُ التَّوَاتُرِ، وَزِيَادَةٌ»، «لِأَنَّ ذَلِكَ طَرَأَ عَلَيْهِ فِي وَسَطِ إِسْنَادِهِ» لا من أوّله.',
  reference = 'مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)، ت نور الدين عتر (دار الفكر بسوريا، ١٤٠٦هـ): ص٢٦٧–٢٦٨ (النوع الموفي ثلاثين: معرفة المشهور من الحديث) | الكلمات المفتاحية: الحديث المتواتر، حديث الآحاد',
  evidence = 'مقدمة ابن الصلاح ص٢٦٧ تُدرج المتواترَ تحت المشهور لا قسيمًا للآحاد ابتداءً: «وَمِنَ الْمَشْهُورِ: الْمُتَوَاتِرُ الَّذِي يَذْكُرُهُ أَهْلُ الْفِقْهِ وَأُصُولِهِ، وَأَهْلُ الْحَدِيثِ لَا يَذْكُرُونَهُ بِاسْمِهِ الْخَاصِّ الْمُشْعِرِ بِمَعْنَاهُ الْخَاصِّ»، وعلّةُ ذلك منصوصةٌ عنده: «وَلَعَلَّ ذَلِكَ لِكَوْنِهِ لَا تَشْمَلُهُ صِنَاعَتُهُمْ، وَلَا يَكَادُ يُوجَدُ فِي رِوَايَاتِهِمْ». وحدُّه فيه: «فَإِنَّهُ عِبَارَةٌ عَنِ الْخَبَرِ الَّذِي يَنْقُلُهُ مَنْ يَحْصُلُ الْعِلْمُ بِصِدْقِهِ ضَرُورَةً، وَلَا بُدَّ فِي إِسْنَادِهِ مِنِ اسْتِمْرَارِ هَذَا الشَّرْطِ فِي رُوَاتِهِ مِنْ أَوَّلِهِ إِلَى مُنْتَهَاهُ». 🔑 وأدقُّ ما في الموضع أن ابن الصلاح ينصّ ص٢٦٨ على عزّة المثال: «وَمَنْ سُئِلَ عَنْ إِبْرَازِ مِثَالٍ لِذَلِكَ فِيمَا يُرْوَى مِنَ الْحَدِيثِ أَعْيَاهُ تَطَلُّبُهُ»، ويُخرِج حديثَ «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ» منه: «لَيْسَ مِنْ ذَلِكَ بِسَبِيلٍ، وَإِنْ نَقَلَهُ عَدَدُ التَّوَاتُرِ، وَزِيَادَةٌ»، لأن «لِأَنَّ ذَلِكَ طَرَأَ عَلَيْهِ فِي وَسَطِ إِسْنَادِهِ» — وهو تطبيقٌ لشرط استمرار العدد في كلّ الطبقات. ⚠️ فوصفُ التقسيم بأنه ‹تقسيم أساسي في علم مصطلح الحديث› مبتورٌ: المصطلحُ الخاصّ للمتواتر عند ابن الصلاح مأخوذٌ عن أهل الفقه وأصولِه لا عن أهل الحديث، وحدُّه بحصول العلم الضروريّ لا بعددٍ مسمًّى.',
  verification_status = 'verified'
WHERE id = '406f6138-ea64-48aa-934d-bcaaba879a5c'
  AND reference = 'كتب مصطلح الحديث | الكلمات المفتاحية: الحديث المتواتر، حديث الآحاد'
  AND evidence = 'تقسيم أساسي في علم مصطلح الحديث.'
  AND answer = 'المتواتر ما رواه جمع كثير يستحيل تواطؤهم على الكذب في كل طبقات السند، وهو يفيد اليقين القطعي. وحديث الآحاد ما لم يبلغ هذا العدد، وهو يفيد الظن الراجح، وأغلب أحاديث الأحكام من هذا النوع.';

-- 42f4ef19 | من هم أصحاب الكتب الستة في الحديث؟
UPDATE qa_questions SET
  answer = 'أصحابُ الكتب الستة في الاصطلاح المتأخّر المستقرّ هم: البخاري، ومسلم، وأبو داود، والترمذي، والنسائي، وابنُ ماجه. على أنّ هذا العدد لم يستقرّ إلا بعد ابن الصلاح؛ فمقدمتُه — وهي أصلُ فنّ المصطلح — إنما تنصّ على **الكتب الخمسة** بأسمائها: «كُتُبُ الْمَسَانِيدِ غَيْرُ مُلْتَحِقَةٍ بِالْكُتُبِ الْخَمْسَةِ الَّتِي هِيَ: الصَّحِيحَانِ، وَسُنَنُ أَبِي دَاوُدَ، وَسُنَنُ النَّسَائِيِّ، وَجَامِعُ التِّرْمِذِيِّ»، وقد رتّبها على المسانيد كمسند أحمد وأبي داود الطيالسي وغيرهما: «فَلِهَذَا تَأَخَّرَتْ مَرْتَبَتُهَا - وَإِنْ جَلَّتْ لِجَلَالَةِ مُؤَلِّفِيهَا - عَنْ مَرْتَبَةِ الْكُتُبِ الْخَمْسَةِ»، لأن أصحاب المسانيد يُخرِجون في مسند كلّ صحابيّ ما رووه من حديثه غيرَ متقيّدين بأن يكون محتجًّا به. ويلزم التنبيهُ على أمرٍ مهمّ: كونُ الحديث في أحد هذه الكتب لا يعني بمجرّده صحّتَه، إلا في الصحيحين؛ فقد ردّ ابنُ الصلاح دعوى الاتفاق على صحّتها: نقل أنّ «وَذَكَرَ الْحَافِظُ أَبُو الطَّاهِرِ السِّلَفِيُّ الْكُتُبَ الْخَمْسَةَ»، وقال: «اتَّفَقَ عَلَى صِحَّتِهَا عُلَمَاءُ الشَّرْقِ وَالْغَرْبِ»، ثم عقّب: «وَهَذَا تَسَاهُلٌ؛ لِأَنَّ فِيهَا مَا صَرَّحُوا بِكَوْنِهِ ضَعِيفًا أَوْ مُنْكَرًا أَوْ نَحْوَ ذَلِكَ مِنْ أَوْصَافِ الضَّعِيفِ»، واحتجّ بتصريح أصحابها أنفسِهم: «وَصَرَّحَ أَبُو دَاوُدَ فِيمَا قَدَّمْنَا رِوَايَتَهُ عَنْهُ بِانْقِسَامِ مَا فِي كِتَابِهِ إِلَى صَحِيحٍ وَغَيْرِهِ، وَالتِّرْمِذِيُّ مُصَرِّحٌ فِيمَا فِي كِتَابِهِ بِالتَّمْيِيزِ بَيْنَ الصَّحِيحِ وَالْحَسَنِ»؛ ولذلك قرّر: «وَلَا يَكْفِي فِي ذَلِكَ مُجَرَّدُ كَوْنِهِ مَوْجُودًا فِي كِتَابِ أَبِي دَاوُدَ، وَكِتَابِ التِّرْمِذِيِّ، وَكِتَابِ النَّسَائِيِّ، وَسَائِرِ مَنْ جَمَعَ فِي كِتَابِهِ بَيْنَ الصَّحِيحِ وَغَيْرِهِ». فهي أشهرُ المجاميع المرتَّبة على الأبواب وأجلُّها، ويبقى الحكمُ على أفراد أحاديثها بالنظر في أسانيدها.',
  reference = 'مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)، ت نور الدين عتر (دار الفكر بسوريا، ١٤٠٦هـ): ص٢١ و٣٧–٣٨ و٤٠ (النوع الأول: معرفة الصحيح، والنوع الثاني: معرفة الحسن) | الكلمات المفتاحية: الكتب الستة، البخاري، مسلم',
  evidence = '🔑 مقدمة ابن الصلاح — أصلُ الفنّ — لا تعرف ‹الكتب الستة› أصلًا، بل تنصّ على **خمسة** بأسمائها ص٣٧: «كُتُبُ الْمَسَانِيدِ غَيْرُ مُلْتَحِقَةٍ بِالْكُتُبِ الْخَمْسَةِ الَّتِي هِيَ: الصَّحِيحَانِ، وَسُنَنُ أَبِي دَاوُدَ، وَسُنَنُ النَّسَائِيِّ، وَجَامِعُ التِّرْمِذِيِّ»، وص٣٨: «فَلِهَذَا تَأَخَّرَتْ مَرْتَبَتُهَا - وَإِنْ جَلَّتْ لِجَلَالَةِ مُؤَلِّفِيهَا - عَنْ مَرْتَبَةِ الْكُتُبِ الْخَمْسَةِ». و**مسحٌ سالبٌ حرفيّ** على الكتاب كلِّه: لفظا ‹ابن ماجه›/‹ماجة› و‹الكتب الستة› **معدومةٌ فيه ⇒ ٠ نتيجة**، بينما «الكتب الخمسة» موضعان؛ فعدُّ الستة اصطلاحٌ استقرّ بعد ابن الصلاح لا في زمانه. 🚩 وأخطرُ من ذلك وصفُها بأنها ‹أوثق مجاميع الحديث› مطلقًا، فقد ردّ ابنُ الصلاح ص٤٠ هذا الإطلاق بعينه على قائله: «وَذَكَرَ الْحَافِظُ أَبُو الطَّاهِرِ السِّلَفِيُّ الْكُتُبَ الْخَمْسَةَ»، وقال: «اتَّفَقَ عَلَى صِحَّتِهَا عُلَمَاءُ الشَّرْقِ وَالْغَرْبِ»، فعقّب ابنُ الصلاح: «وَهَذَا تَسَاهُلٌ؛ لِأَنَّ فِيهَا مَا صَرَّحُوا بِكَوْنِهِ ضَعِيفًا أَوْ مُنْكَرًا أَوْ نَحْوَ ذَلِكَ مِنْ أَوْصَافِ الضَّعِيفِ»، ومستندُه تصريحُ المصنِّفَين أنفسِهما: «وَصَرَّحَ أَبُو دَاوُدَ فِيمَا قَدَّمْنَا رِوَايَتَهُ عَنْهُ بِانْقِسَامِ مَا فِي كِتَابِهِ إِلَى صَحِيحٍ وَغَيْرِهِ، وَالتِّرْمِذِيُّ مُصَرِّحٌ فِيمَا فِي كِتَابِهِ بِالتَّمْيِيزِ بَيْنَ الصَّحِيحِ وَالْحَسَنِ». ولذلك نصَّ ص٢١: «وَلَا يَكْفِي فِي ذَلِكَ مُجَرَّدُ كَوْنِهِ مَوْجُودًا فِي كِتَابِ أَبِي دَاوُدَ، وَكِتَابِ التِّرْمِذِيِّ، وَكِتَابِ النَّسَائِيِّ، وَسَائِرِ مَنْ جَمَعَ فِي كِتَابِهِ بَيْنَ الصَّحِيحِ وَغَيْرِهِ».',
  verification_status = 'verified'
WHERE id = '42f4ef19-a10b-4be9-967b-2b40c2fbeba1'
  AND reference = 'كتب مصطلح الحديث | الكلمات المفتاحية: الكتب الستة، البخاري، مسلم'
  AND evidence = 'تصنيف متعارف عليه بين علماء الحديث عبر القرون.'
  AND answer = 'البخاري ومسلم وأبو داود والترمذي والنسائي وابن ماجه، وكتبهم هي أشهر وأوثق مجاميع الحديث النبوي المرتبة.';

-- 1187ce3c | ما هي أشهر طبقات رواة الحديث؟
UPDATE qa_questions SET
  answer = '«معرفة طبقات الرواة والعلماء» نوعٌ مستقلٌّ عند ابن الصلاح في مقدمته: «النَّوْعُ الثَّالِثُ وَالسِّتُّونَ: مَعْرِفَةُ طَبَقَاتِ الرُّوَاةِ وَالْعُلَمَاءِ»، «وَذَلِكَ مِنَ الْمُهِمَّاتِ الَّتِي افْتَضَحَ بِسَبَبِ الْجَهْلِ بِهَا غَيْرُ وَاحِدٍ مِنَ الْمُصَنِّفِينَ وَغَيْرِهِمْ». وأصلُ الطبقة: «وَالطَّبَقَةُ فِي اللُّغَةِ عِبَارَةٌ عَنِ الْقَوْمِ الْمُتَشَابِهِينَ»؛ فإذا نُظر إلى أصل صفة الصحبة كان الترتيبُ الأشهر: «فَالصَّحَابَةُ بِأَسْرِهِمْ طَبَقَةٌ أُولَى، وَالتَّابِعُونَ طَبَقَةٌ ثَانِيَةٌ، وَأَتْبَاعُ التَّابِعِينَ ثَالِثَةٌ، وَهَلُمَّ جَرًّا». والصحابيّ في المعروف من طريقة أهل الحديث: «كُلَّ مُسْلِمٍ رَأَى رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَهُوَ مِنَ الصَّحَابَةِ»، وقال البخاريُّ في صحيحه: «مَنْ صَحِبَ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَوْ رَآهُ مِنَ الْمُسْلِمِينَ، فَهُوَ مِنْ أَصْحَابِهِ»؛ والتابعيّ قال الخطيب: «التَّابِعِيُّ مَنْ صَحِبَ الصَّحَابِيَّ». والمهمّ أنّ التقسيم إلى طبقاتٍ **إضافيٌّ** لا سُلَّمٌ واحدٌ مطّرد؛ قال ابن الصلاح: «فَرُبَّ شَخْصَيْنِ يَكُونَانِ مِنْ طَبَقَةٍ وَاحِدَةٍ لِتَشَابُهِهِمَا بِالنِّسْبَةِ إِلَى جِهَةٍ، وَمِنْ طَبَقَتَيْنِ بِالنِّسْبَةِ إِلَى جِهَةٍ أُخْرَى لَا يَتَشَابَهَانِ فِيهَا» — فأنسُ بنُ مالك وأصاغرُ الصحابة مع العشرة طبقةٌ واحدةٌ باعتبار الصحبة، فإذا نُظر إلى السوابق والمراتب: «وَإِذَا نَظَرْنَا إِلَى تَفَاوُتِ الصَّحَابَةِ فِي سَوَابِقِهِمْ وَمَرَاتِبِهِمْ كَانُوا ... بِضْعَ عَشْرَةَ طَبَقَةً». وكذلك التابعون، ذكر الحاكمُ «أَنَّ التَّابِعِينَ عَلَى خَمْسَ عَشْرَةَ طَبَقَةً» أُولاها الذين لحقوا العشرة كسعيد بن المسيّب وقيس بن أبي حازم. وثمرةُ هذا الفنّ الأولى معرفةُ الاتصال والانقطاع: «هَذَا وَمَعْرِفَةُ الصَّحَابَةِ أَصْلٌ أَصِيلٌ يُرْجَعُ إِلَيْهِ فِي مَعْرِفَةِ الْمُرْسَلِ وَالْمُسْنَدِ»، ولذلك «وَالْبَاحِثُ النَّاظِرُ فِي هَذَا الْفَنِّ يَحْتَاجُ إِلَى مَعْرِفَةِ الْمَوَالِيدِ وَالْوَفَيَاتِ، وَمَنْ أَخَذُوا عَنْهُ وَمَنْ أَخَذَ عَنْهُمْ».',
  reference = 'مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)، ت نور الدين عتر (دار الفكر بسوريا، ١٤٠٦هـ): ص٣٩٨–٣٩٩ (النوع الثالث والستون: معرفة طبقات الرواة والعلماء)، وص٢٩٣ و٣٠٢ (النوعان التاسع والثلاثون والموفي أربعين) | الكلمات المفتاحية: طبقات الرواة',
  evidence = 'مقدمة ابن الصلاح تُفرد لهذا نوعًا مستقلًّا: «النَّوْعُ الثَّالِثُ وَالسِّتُّونَ: مَعْرِفَةُ طَبَقَاتِ الرُّوَاةِ وَالْعُلَمَاءِ»، وتنصّ على أهميّته: «وَذَلِكَ مِنَ الْمُهِمَّاتِ الَّتِي افْتَضَحَ بِسَبَبِ الْجَهْلِ بِهَا غَيْرُ وَاحِدٍ مِنَ الْمُصَنِّفِينَ وَغَيْرِهِمْ». وحدُّ الطبقة ص٣٩٩: «وَالطَّبَقَةُ فِي اللُّغَةِ عِبَارَةٌ عَنِ الْقَوْمِ الْمُتَشَابِهِينَ»، وعليه: «فَالصَّحَابَةُ بِأَسْرِهِمْ طَبَقَةٌ أُولَى، وَالتَّابِعُونَ طَبَقَةٌ ثَانِيَةٌ، وَأَتْبَاعُ التَّابِعِينَ ثَالِثَةٌ، وَهَلُمَّ جَرًّا». 🔑 والعيبُ الأكبر في الجواب السابق أنه جعلها سُلَّمًا واحدًا مطّردًا بحسب العصور، والنصُّ صريحٌ في أنها **إضافيّةٌ تختلف باختلاف جهة النظر**: «فَرُبَّ شَخْصَيْنِ يَكُونَانِ مِنْ طَبَقَةٍ وَاحِدَةٍ لِتَشَابُهِهِمَا بِالنِّسْبَةِ إِلَى جِهَةٍ، وَمِنْ طَبَقَتَيْنِ بِالنِّسْبَةِ إِلَى جِهَةٍ أُخْرَى لَا يَتَشَابَهَانِ فِيهَا»، حتى إنّ الصحابة أنفسَهم «وَإِذَا نَظَرْنَا إِلَى تَفَاوُتِ الصَّحَابَةِ فِي سَوَابِقِهِمْ وَمَرَاتِبِهِمْ كَانُوا ... بِضْعَ عَشْرَةَ طَبَقَةً»، والتابعون «أَنَّ التَّابِعِينَ عَلَى خَمْسَ عَشْرَةَ طَبَقَةً» عند الحاكم. 🚩 وحدُّ الصحابيّ المنقول ص٢٩٣ بالرؤية لا باللقاء: «كُلَّ مُسْلِمٍ رَأَى رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَهُوَ مِنَ الصَّحَابَةِ». 🚩 وثمرةُ الفنّ المنصوصة ص٣٠٢ ليست الجرحَ والتعديل: «هَذَا وَمَعْرِفَةُ الصَّحَابَةِ أَصْلٌ أَصِيلٌ يُرْجَعُ إِلَيْهِ فِي مَعْرِفَةِ الْمُرْسَلِ وَالْمُسْنَدِ».',
  verification_status = 'verified'
WHERE id = '1187ce3c-808d-4d30-9060-0721f8fc3161'
  AND reference = 'كتب مصطلح الحديث | الكلمات المفتاحية: طبقات الرواة'
